-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- TITUS - HIN Combined
-- Generated: 2026-01-20T22:33:30.313Z

-- c001-v001: Paulos, daas Parameshwar–ka, prairit aur Yeshu Khristos–ka, ke-anusaar vishwaas chunon Parameshwar–ke, aur samajh satya, jo ke-anusaar bhakti;
-- c001-v002: par aasha jivan anant, jo vachan–diya us jhooth–na–bolnewale, Parameshwar–ne, se–pahle samay anant;
-- c001-v003: pragtit–kiya aur, samay apne, us vachan uska, mein prachaar jo saunpa–gaya mujhe, ke-anusaar aadesh us Uddharkarta hamare, Parameshwar;
-- c001-v004: Titos–ko, sachche putr, ke-anusaar saanjhi vishwaas: anugrah aur shanti se Parameshwar Pita, aur Khristos Yeshu, us Uddharkarta hamare.
-- c001-v005: Is liye, chhoda tujhe mein Krētē, taaki jo baaki theek–kare, aur niyukt–kare mein–har nagar pracheen, jaise maine tujhe aadesh–diya,
-- c001-v006: yadi koi ho nirdosh, ek patni pati, bachche rakhne-waala vishwaasi, nahin mein aarop apradh ya avagya.
-- c001-v007: chahiye kyonki us adhyaksh nirdosh hona, jaise Parameshwar–ka bhandaari; nahin ahankaari, nahin krodhi, nahin sharaabi, nahin maarane-waala, nahin laabh-lobhi;
-- c001-v008: parantu atithi-sevak, bhalaayi-premi, sanyami, dharmik, pavitra, aatma-santulit;
-- c001-v009: pakde-rakhne-waala us, ke-anusaar us shiksha, vishwaasyogya vachan, taaki samarth ho bhi samjhaane mein us shiksha jo svasth, aur un virodh–karnewaalon dokhh-dena.
-- c001-v010: Hain kyonki bahut ‹aur› avagya, vyarth-baatein, aur dhokhebaaz, khaaskr woh se us khatna,
-- c001-v011: jinhen chahiye chup–karaana, jo poore gharon ulat–dete, sikhaate-hue jo nahin chahiye, gande laabh ke-liye.
-- c001-v012: kaha kisine se unke, apna unka, nabi, Krēti hamesha jhoothe, bure janwar, pet aalsi.
-- c001-v013: woh sakshi ye hai satya; is jis kaaran daant unhen kathorata–se, taaki svasth–hon mein us vishwaas,
-- c001-v014: nahin dhyaan–dene-waale Yahudi kathaon aur aadeshon manushyon, phernewaalon us satya.
-- c001-v015: sab shuddh un shuddh-logon; un aur ashuddh–hue aur avishwaasi, kuchh–nahin shuddh; parantu ashuddh–hai unka bhi woh mann, aur woh antahkaran.
-- c001-v016: Parameshwar maante–hain jaanana; un aur karmon, inkaar–karte, ghrinit hote-hue aur avagya, aur ke-prati har kaam bhalee, naakaabil.
-- c002-v001: Tu aur bol jo yogya–hai us svasth shiksha:
-- c002-v002: boodhe-purusha sacheta hon, sabhya, sanyami, svasth mein vishwaas, mein prem, mein dheeraj;
-- c002-v003: boodhi-mahilayen isi–prakaar, mein aacharan pavitra-yogya, nahin nindak, na–hi daaru bahut daasi, bhalaayi-sikhaanewali,
-- c002-v004: taaki samjhaayen un javaanon, pati-premi hona, bachche-premi,
-- c002-v005: sanyami, pavitra, ghar-rakhne-waali, bhalee, adheen–rahnewali un apne patiyon, taaki nahin woh vachan us Parameshwar–ka ninda–ho.
-- c002-v006: Un javaanon, isi–prakaar, samjhaa sanyami–hona,
-- c002-v007: ke-baare-mein sab apne–aap–ko dikhaate–hue aadarsh bhalee karmon; mein us shiksha shuddhtaa, gambheertaa,
-- c002-v008: vachan svasth, nirdosh, taaki woh se virodhi lajjit–ho, kuchh–nahin rakhte–hue kahne ke-baare-mein hamaare bura.
-- c002-v009: daasen apne swaamiyon adheen–rahein, mein sabon prasann–karnewale hon, nahin virodh–karnewale;
-- c002-v010: nahin churaanewale, parantu sab vishwaasyogytaa dikhaanewale bhalee, taaki us shiksha us us Uddharkarta hamare, Parameshwar, sushobhit–karein mein sabon.
-- c002-v011: Pragtit–hua kyonki woh anugrah us Parameshwar–ka, uddhar-karnewala sab manushyon;
-- c002-v012: sikhlaanewala hamen taaki, inkaar–karke us adharm aur un sansaarik ichchhaon, sanyam–se aur dharm–se aur bhakti–se jiyein, mein is vartamaan yug;
-- c002-v013: intazaar–karte-hue us dhanya aasha, aur pragatya us mahima us mahaan Parameshwar aur Uddharkarta hamare, Khristos Yeshu;
-- c002-v014: jis–ne diya apne–aap ke-liye hamaare, taaki chhudaa–le hamen se sabhi apaadharmi, aur shuddh–kare apne–liye prajaon apni, jalsheel bhalee karmon.
-- c002-v015: Ye bol, aur samjhaa, aur daant ke-saath sabhi adhikaar. koi–nahin tera tuchhsamjhe.
-- c003-v001: Yaad–dila unhen shashakon, adhikaariyon, adheen–rahna, maanna; ke-prati har kaam bhalee, taiyaar hona;
-- c003-v002: kisi ninda–na–karna, ladaayi-heen hona, narm, sabhi dikhaanewale narmtaa ke-prati sab manushyon.
-- c003-v003: The kyonki kabhi bhi hum moorakh, avagya, bhatke–hue, daas–the ichchhaon aur sukh vividh, mein buraai aur daah bitate–hue, ghrina-yogya, nafrat–karnewale ek-doosre.
-- c003-v004: jab aur woh bhalaayi aur woh manushya-prem pragtit–hua, us Uddharkarta hamare, Parameshwar,
-- c003-v005: nahin se karmon un mein dharmiktaa, jo kiye hum–ne, parantu ke-anusaar us uski daya, bachaaya hamen, ke-dwara snan pun-utpatti, aur naye-karne Aatma Pavitra;
-- c003-v006: jise undela par hamen bahutaayat–se, ke-dwara Yeshu Khristos, us Uddharkarta hamare,
-- c003-v007: taaki dharmik-thahrae us uske anugrah, waarisen ho-jaayen, ke-anusaar aasha jivan anant.
-- c003-v008: Vishwaasyogya woh vachan, aur ke-baare-mein in chaahta–hoon tujhe dridh–karna, taaki dhyaan–rakhein bhalee karmon ke-liye–aage-rahnewale, woh vishwaas–kiye–hue Parameshwar. ye hai bhalee aur laabhdaayak un manushyon.
-- c003-v009: moorkh aur vivaadon aur vanshavaaliyon aur jhagdon aur ladaaiyon vyavasthik, door–reh; hain kyonki laabh-heen aur vyarth.
-- c003-v010: vidharmik manushya, ke-baad ek aur doosri chetaavani, tyaag–de,
-- c003-v011: jaante–hue ki bigad–gaya–hai woh aisa, aur paap–karta, hote-hue sva-doshi.
-- c003-v012: Jab bhejon Artemas pas tere, ya Tuchikos, prayaas–kar aana pas mere ko Nikopolis; wahan kyonki tay–kiya–hai sardi–bitaana.
-- c003-v013: Zēnas us vyavasthik aur Apollos lagn–se aage–bhej, taaki kuchh–nahin unhen kami–ho.
-- c003-v014: seekhein aur bhi woh hamaare, bhalee karmon ke-liye–aage-rahnewale, ke-liye un zaroori zaroortein, taaki nahin hon nishshhal.
-- c003-v015: Namaskar–karate–hain tujhe, woh ke-saath mere sab. namaskar–kar un prem–karnewaalon hamen mein vishwaas. Woh anugrah ke-saath sab tumhaare. <Amen>.

